  @moduledoc "A case in a listing: no party, no identifier, no name. Read the case for its parties."

  defstruct [
    :created_at,
    :current_state,
    :external_reference,
    :id,
    :kind,
    :livemode,
    :policy_version_id,
    :status,
    :status_market,
    :updated_at,
    :workflow_definition_id,
    :workflow_version_id
  ]

  @typedoc """
  * `created_at`: When the case was opened, to the nanosecond the store keeps.
  * `kind` (one of `"KYC"`, `"KYB"`, `"AGE"`)
  * `livemode`: False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
  * `status` (one of `"open"`, `"processing"`, `"awaiting_input"`, `"in_review"`, `"approved"`, `"rejected"`, `"cancelled"`, `"expired"`)
  * `status_market` (one of `"PROCESSING"`, `"PENDING_OCR"`, `"PENDING"`, `"APPROVED"`, `"REPROVED"`, `"BLOCKED"`, `"CANCELLED"`, `"EXPIRED"`): The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision.
  * `workflow_version_id`: The workflow version the case is pinned to once started.
  """
  @type t :: %__MODULE__{
          created_at: String.t(),
          current_state: String.t(),
          external_reference: String.t(),
          id: String.t(),
          kind: String.t(),
          livemode: boolean(),
          policy_version_id: String.t() | nil,
          status: String.t(),
          status_market: String.t(),
          updated_at: String.t(),
          workflow_definition_id: String.t() | nil,
          workflow_version_id: String.t() | nil
        }

  @doc "Builds a CaseSummary from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      created_at: Map.fetch!(data, "created_at"),
      current_state: Map.fetch!(data, "current_state"),
      external_reference: Map.fetch!(data, "external_reference"),
      id: Map.fetch!(data, "id"),
      kind: Map.fetch!(data, "kind"),
      livemode: Map.fetch!(data, "livemode"),
      policy_version_id: data["policy_version_id"],
      status: Map.fetch!(data, "status"),
      status_market: Map.fetch!(data, "status_market"),
      updated_at: Map.fetch!(data, "updated_at"),
      workflow_definition_id: data["workflow_definition_id"],
      workflow_version_id: data["workflow_version_id"]
    }
  end
end

