defmodule Kuaa.Document do
  @moduledoc "A document of a case: its kind and where it stands. No byte of the file, its artifact or anything read from it leaves."

  defstruct [
    :capture,
    :captured_at,
    :decision,
    :document_type,
    :id,
    :in_force,
    :party_id,
    :received_at,
    :requirement,
    :side,
    :status
  ]

  @typedoc """
  * `capture` (one of `"document"`, `"selfie"`)
  * `captured_at`: When the client said it was captured, or null.
  * `decision`: The reviewer's decision in force about the document, the newest one, or null while nobody decided. The reviewer's reason never leaves through the API.
  * `document_type`: The type of a document capture, such as CNH or RG; null for a selfie.
  * `id`: The document row.
  * `in_force`: False for a document a newer capture replaced or that could not be used.
  * `party_id`: The party who presented it.
  * `received_at`: When the file was received.
  * `requirement` (one of `"identity_document"`, `"selfie"`): What the document answers of what the case's workflow requires.
  * `side`: front, back or single for a document capture; null for a selfie.
  * `status`: received, processed once its checks ran, refused when it cannot be used, or superseded when a newer capture replaced it.
  """
  @type t :: %__MODULE__{
          capture: String.t(),
          captured_at: String.t() | nil,
          decision: Kuaa.DocumentDecision.t() | nil,
          document_type: String.t() | nil,
          id: String.t(),
          in_force: boolean(),
          party_id: String.t(),
          received_at: String.t(),
          requirement: String.t(),
          side: String.t() | nil,
          status: String.t()
        }

  @doc "Builds a Document from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      capture: Map.fetch!(data, "capture"),
      captured_at: data["captured_at"],
      decision: with(value when not is_nil(value) <- data["decision"], do: Kuaa.DocumentDecision.from_map(value)),
      document_type: data["document_type"],
      id: Map.fetch!(data, "id"),
      in_force: Map.fetch!(data, "in_force"),
      party_id: Map.fetch!(data, "party_id"),
      received_at: Map.fetch!(data, "received_at"),
      requirement: Map.fetch!(data, "requirement"),
      side: data["side"],
      status: Map.fetch!(data, "status")
    }
  end
end

