defmodule Kuaa.DossierParty do
  @moduledoc "A party in the dossier. Without party.pii.view the identifier is masked and the names and dates are left out; meta.full_pii says which."

  defstruct [
    :birth_date,
    :cnae,
    :cnpj,
    :cpf,
    :full_name,
    :id,
    :identity_id,
    :kind,
    :natureza_juridica,
    :nome_fantasia,
    :primary,
    :razao_social,
    :situacao,
    :social_name
  ]

  @typedoc """
  * `birth_date`: The birth date of a PERSON, when known. Present only for a key with party.pii.view.
  * `cnae`: The main CNAE activity code of a BUSINESS. Present only for a key with party.pii.view.
  * `cnpj`: The CNPJ of a BUSINESS as text. In full (normalized, ^[0-9A-Z]{12}[0-9]{2}$) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *, as ************95.
  * `cpf`: The CPF of a PERSON as text. In full (11 digits) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *, as *********25.
  * `full_name`: The civil name of a PERSON. Present only for a key with party.pii.view.
  * `id`: The party's identifier.
  * `identity_id`: The resolved identity the party was matched to, or null before resolution.
  * `kind` (one of `"PERSON"`, `"BUSINESS"`)
  * `natureza_juridica`: The legal nature code of a BUSINESS. Present only for a key with party.pii.view.
  * `nome_fantasia`: The trade name of a BUSINESS. Present only for a key with party.pii.view.
  * `primary`: Whether the party is the primary subject of the case.
  * `razao_social`: The registered name of a BUSINESS. Present only for a key with party.pii.view.
  * `situacao`: The registration status of a BUSINESS. Present only for a key with party.pii.view.
  * `social_name`: The social name of a PERSON, empty when none. Present only for a key with party.pii.view.
  """
  @type t :: %__MODULE__{
          birth_date: String.t() | nil,
          cnae: String.t() | nil,
          cnpj: String.t() | nil,
          cpf: String.t() | nil,
          full_name: String.t() | nil,
          id: String.t(),
          identity_id: String.t() | nil,
          kind: String.t(),
          natureza_juridica: String.t() | nil,
          nome_fantasia: String.t() | nil,
          primary: boolean(),
          razao_social: String.t() | nil,
          situacao: String.t() | nil,
          social_name: String.t() | nil
        }

  @doc "Builds a DossierParty from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
