defmodule Kuaa.Party do
  @moduledoc "A person or a company in a case. The contact data sent with it is stored encrypted and never answered back."

  defstruct [
    :birth_date,
    :cnae,
    :cnpj,
    :cpf,
    :full_name,
    :id,
    :identity_id,
    :kind,
    :natureza_juridica,
    :nome_fantasia,
    :primary,
    :razao_social,
    :situacao,
    :social_name
  ]

  @typedoc """
  * `birth_date`: The birth date of a PERSON, when known.
  * `cnae`: The main CNAE activity code of a BUSINESS.
  * `cnpj`: The CNPJ of a BUSINESS as text, normalized: alphanumeric, twelve characters from 0-9 and A-Z followed by two check digits. Absent for a PERSON.
  * `cpf`: The CPF of a PERSON as text, normalized to its 11 digits. Absent for a BUSINESS.
  * `full_name`: The civil name of a PERSON.
  * `id`: The party's identifier.
  * `identity_id`: The resolved identity the party was matched to, or null before resolution.
  * `kind` (one of `"PERSON"`, `"BUSINESS"`)
  * `natureza_juridica`: The legal nature code of a BUSINESS.
