defmodule Kuaa.PartyProfile do
  @moduledoc "PartyProfile is an object of KUAA's API."

  defstruct [
    :cases,
    :cnpj,
    :cpf,
    :id,
    :identity,
    :kind,
    :livemode,
    :monitoring,
    :name,
    :party_ids,
    :screenings,
    :tags
  ]

  @typedoc """
  * `cases`: The cases it takes part in, newest first. Null for a key without case.list.
  * `cnpj`: The CNPJ of a BUSINESS as text, which may be alphanumeric. In full for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *.
  * `cpf`: The CPF of a PERSON as text. In full (11 digits) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *.
  * `id`: The profile: the id of the first party row of this CPF or CNPJ in the organization. GET /v1/parties/{id} takes it, or any party id of the same person or company.
  * `identity`: What KUAA verified about the identifier across cases. Null when nothing was, or for a key without identity.view.
  * `kind` (one of `"PERSON"`, `"BUSINESS"`)
  * `livemode`: False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
  * `name`: The full name of a person or the razão social of a company, from its newest party row. Null without party.pii.view.
  * `party_ids`: Every party row of this CPF or CNPJ in the organization, oldest first.
  * `screenings`: The latest screening of each list among its party rows. Null for a key without evidence.view.
  * `tags`: The tags its party rows carry, without repeats. Null for a key without tag.list.
  """
  @type t :: %__MODULE__{
          cases: [Kuaa.PartyProfileCase.t()] | nil,
          cnpj: String.t() | nil,
          cpf: String.t() | nil,
          id: String.t(),
          identity: Kuaa.Identity.t() | nil,
          kind: String.t(),
          livemode: boolean(),
          monitoring: Kuaa.Monitoring.t(),
          name: String.t() | nil,
          party_ids: [String.t()],
          screenings: [Kuaa.Screening.t()] | nil,
          tags: [Kuaa.PartyProfileTag.t()] | nil
        }

  @doc "Builds a PartyProfile from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      cases: with(value when not is_nil(value) <- data["cases"], do: Enum.map(value, &Kuaa.PartyProfileCase.from_map/1)),
      cnpj: data["cnpj"],
      cpf: data["cpf"],
      id: Map.fetch!(data, "id"),
      identity: with(value when not is_nil(value) <- data["identity"], do: Kuaa.Identity.from_map(value)),
      kind: Map.fetch!(data, "kind"),
      livemode: Map.fetch!(data, "livemode"),
      monitoring: Kuaa.Monitoring.from_map(Map.fetch!(data, "monitoring")),
      name: data["name"],
      party_ids: Map.fetch!(data, "party_ids"),
      screenings: with(value when not is_nil(value) <- data["screenings"], do: Enum.map(value, &Kuaa.Screening.from_map/1)),
      tags: with(value when not is_nil(value) <- data["tags"], do: Enum.map(value, &Kuaa.PartyProfileTag.from_map/1))
    }
  end
end

defmodule Kuaa.PartyProfileCase do
  @moduledoc "PartyProfileCase is an object of KUAA's API."

  defstruct [
    :case_id,
    :created_at,
    :external_reference,
    :kind,
    :party_id,
    :primary,
    :status,
    :status_market
  ]

  @typedoc """
  * `kind` (one of `"KYC"`, `"KYB"`, `"AGE"`)
  * `party_id`: The party row of this person or company in the case.
  * `primary`: Whether the case is about this person or company.
  * `status` (one of `"open"`, `"processing"`, `"awaiting_input"`, `"in_review"`, `"approved"`, `"rejected"`, `"cancelled"`, `"expired"`)
  * `status_market` (one of `"PROCESSING"`, `"PENDING_OCR"`, `"PENDING"`, `"APPROVED"`, `"REPROVED"`, `"BLOCKED"`, `"CANCELLED"`, `"EXPIRED"`): The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision.
  """
  @type t :: %__MODULE__{
          case_id: String.t(),
          created_at: String.t(),
          external_reference: String.t(),
          kind: String.t(),
          party_id: String.t(),
