          status: String.t(),
          status_market: String.t()
        }

  @doc "Builds a PartyProfileCase from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      case_id: Map.fetch!(data, "case_id"),
      created_at: Map.fetch!(data, "created_at"),
      external_reference: Map.fetch!(data, "external_reference"),
      kind: Map.fetch!(data, "kind"),
      party_id: Map.fetch!(data, "party_id"),
      primary: Map.fetch!(data, "primary"),
      status: Map.fetch!(data, "status"),
      status_market: Map.fetch!(data, "status_market")
    }
  end
end

