  @typedoc """
  * `active`: Whether events are delivered. An endpoint turned off keeps its deliveries waiting until it is turned on.
  * `disabled_reason`: Why the endpoint was turned off: consecutive_failures when its deliveries kept giving up, or what the person who turned it off wrote.
  * `id`: The endpoint identifier.
  * `secret`: The signing secret, in clear, this once. It is stored sealed and never answered again; a request replayed with the same Idempotency-Key answers null here. Lost, it is replaced by rotating the endpoint in the backoffice.
  * `url`: The https:// address the deliveries go to.
  """
  @type t :: %__MODULE__{
          active: boolean(),
          created_at: String.t(),
          disabled_at: String.t() | nil,
          disabled_reason: String.t() | nil,
          events: [String.t()],
          id: String.t(),
          name: String.t(),
          secret: String.t() | nil,
          url: String.t()
        }

  @doc "Builds a WebhookCreated from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      active: Map.fetch!(data, "active"),
      created_at: Map.fetch!(data, "created_at"),
      disabled_at: data["disabled_at"],
      disabled_reason: data["disabled_reason"],
      events: Map.fetch!(data, "events"),
      id: Map.fetch!(data, "id"),
      name: Map.fetch!(data, "name"),
      secret: data["secret"],
      url: Map.fetch!(data, "url")
    }
  end
end

defmodule Kuaa.WebhookEvent do
