          source: String.t(),
          specversion: String.t(),
          subject: String.t(),
          time: String.t(),
          type: String.t()
        }

  @doc "Builds a WebhookEvent from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      data: Kuaa.WebhookEventData.from_map(Map.fetch!(data, "data")),
      datacontenttype: Map.fetch!(data, "datacontenttype"),
      id: Map.fetch!(data, "id"),
      source: Map.fetch!(data, "source"),
