defmodule Kuaa.Workflow do
  @moduledoc "Workflow is an object of KUAA's API."

  defstruct [:default, :default_for, :id, :key, :latest_version, :name, :versions]

  @typedoc """
  * `default`: True when a case of some kind runs this workflow when it names none.
  * `default_for`: The case kinds that run this workflow by default.
  * `id`: The workflow definition; POST /v1/cases takes it, or its key, as workflow_definition_id.
  * `key`: The workflow's key, such as br.kyc.
  * `latest_version`: The version a case starting now is pinned to.
  * `versions`: Every published version, newest first.
  """
  @type t :: %__MODULE__{
          default: boolean(),
          default_for: [String.t()],
          id: String.t(),
          key: String.t(),
          latest_version: Kuaa.WorkflowVersion.t(),
          name: String.t(),
          versions: [Kuaa.WorkflowVersion.t()]
        }

  @doc "Builds a Workflow from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      default: Map.fetch!(data, "default"),
      default_for: Map.fetch!(data, "default_for"),
      id: Map.fetch!(data, "id"),
      key: Map.fetch!(data, "key"),
      latest_version: Kuaa.WorkflowVersion.from_map(Map.fetch!(data, "latest_version")),
      name: Map.fetch!(data, "name"),
      versions: Enum.map(Map.fetch!(data, "versions"), &Kuaa.WorkflowVersion.from_map/1)
    }
  end
end

defmodule Kuaa.WorkflowList do
  @moduledoc "WorkflowList is an object of KUAA's API."

  defstruct [:livemode, :workflows]

  @typedoc """
  * `livemode`: False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
